# Cell Cell Компонент ячейки представляет собой стилизованные слоты для контента. Также имеются вспомогательные компоненты (Textbox, TextTitle, TextSubtitle, TextLabel). Они представляют собой стилизованный текст и слот для них. ## Примеры Примеры ### Базовое использование Базовое использование ```tsx
import React from 'react';
import { Avatar, Cell } from '@salutejs/sdds-finai';
import { IconChevronRight } from '@salutejs/plasma-icons';

export function App() {
    return (
        <>
            <Cell
                contentLeft={ <Avatar size="m" url="https://avatars.githubusercontent.com/u/1813468?v=4" /> }
                size="m"
                contentRight={<IconChevronRight color="inherit" size="xs" />}
                title="Title"
                subtitle="Subtitle"
                label="Label"
            />
        </>
    );
}
```

### С использованием своих стилей или встроенных компонентов С использованием своих стилей или встроенных компонентов ```tsx
import React from 'react';
import { Avatar, Cell , CellTextboxLabel , CellTextboxTitle , CellTextboxSubtitle, CellTextbox } from '@salutejs/sdds-finai';
import { IconChevronRight } from '@salutejs/plasma-icons';

export function App() {
    return (
        <>
            <Cell
                contentLeft={ <Avatar size="m" url="https://avatars.githubusercontent.com/u/1813468?v=4" /> }
                size="m"
                contentRight={<IconChevronRight color="inherit" size="xs" />}
            >
                <CellTextbox>
                    <CellTextboxLabel>Label</CellTextboxLabel>
                    <CellTextboxTitle>Title</CellTextboxTitle>
                    <CellTextboxSubtitle>Subtitle</CellTextboxSubtitle>
                    <div style={{'font-size': '12px', opacity: 0.4}}>Caption</div>
                </CellTextbox>
            </Cell>
        </>
    );
}
```
